def proposed_diff_text(
    prepared: list[PreparedFile],
) -> str:
    chunks: list[str] = []

    for item in prepared:
        old_text = normalize_newlines(
            item.original_bytes.decode("utf-8")
        )
        new_text = normalize_newlines(
            item.new_bytes.decode("utf-8")
        )

        chunks.extend(
            difflib.unified_diff(
                old_text.splitlines(keepends=True),
                new_text.splitlines(keepends=True),
                fromfile=f"a/{item.relative_path}",
                tofile=f"b/{item.relative_path}",
                lineterm="\n",
            )
        )

    return "".join(chunks)

def run_build(
    repo: Path,
    spec: dict[str, Any],
) -> list[CheckResult]:
    entries = normalize_check_entries(
        spec,
        "build",
    )

    return run_checks(
        repo,
        entries,
        "build",
    )


def run_tests(
    repo: Path,
    spec: dict[str, Any],
) -> list[CheckResult]:
    entries = normalize_check_entries(
        spec,
        "tests",
    )

    return run_checks(
        repo,
        entries,
        "tests",
    )

